# This is a sample Python script.
import time

# ⚠️ `from ... import *` 只能在模块顶层 —— 原来它写在 read() 里面,
# 那是 SyntaxError("import * only allowed at module level"),整个脚本根本跑不起来。
from pyopenfilegdb import *


def read():
    path = r'D:\work\2024年国土行政区划.gdb'

    ds = OpenFileGDB(path)

    layers = ds.list_layers()
    for layer in layers:
        print(layer)

    cun_layer = ds.get_layer('村行政区划')

    layer_count = cun_layer.record_count
    print(f"图层：{cun_layer.name},要素数量：{layer_count}")
    fields = cun_layer.fields
    for field in fields:
        print(field)

    features = cun_layer.read_features()
    start = time.time()
    var = []
    for feature in features:
        feature.attributes['ZLDWDM']
        g = feature.geometry
        # print(g.wkt())

        # var.append(feature.attributes['ZLDWDM'])
    end = time.time()

    print(len(var))
    print(f"遍历完成,花费时间:{end - start}")
    ds.close()      # 只读也显式关掉,免得句柄挂着

