    # overlay 四算子(difference / union / intersection / symmetric_difference)
    # ⚠️ 这里已经转到 4490(经纬度),面积单位是"平方度"所以很小,用 .6g 才看得见
    dif = buf_1.difference(buf_2)
    print(f"difference 后：面积={dif.area():.6g}  kind={dif.kind}  顶点={dif.point_count}  wkt:{dif.wkt()}")
    uni = buf_1.union(buf_2)
    print(f"union 后：面积={uni.area():.6g}  kind={uni.kind}  wkt:{uni.wkt()}")
    inter = buf_1.intersection(buf_2)
    print(f"intersection 后：面积={inter.area():.6g}  kind={inter.kind}  wkt:{inter.wkt()}")
    sym = buf_1.symmetric_difference(buf_2)
    print(f"symmetric_difference 后：面积={sym.area():.6g}  kind={sym.kind}  wkt:{sym.wkt()}")

