def test_update():
    with OpenFileGDB.open(r'd:/work/test_write.gdb', update=True) as gdb:
        layer = gdb.get_layer('test_write')
        for item in layer.read_features():
            item.attributes['ZLDWMC'] = 'test'
            layer.update_feature(item)
        layer.sync()    # with 退出时也会结账,这里显式写一次更清楚

